5. var builder = WebApplication.CreateBuilder(args);
6. 
7. // Train and save the model at startup
8. var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
9. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
10. TrainModel(dataPath, modelPath);
11. 
12. // Register pooled prediction engine (thread-safe for web use)
13. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
14.     .FromFile(modelPath);
15. 
16. var app = builder.Build();
17. 
18. app.MapGet("/", () => "Churn Predictor API — POST to /predict");
19. 
20. app.MapPost("/predict", (CustomerInput input, PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
21. {
22.     var data = new CustomerData
23.     {
24.         Age = input.Age,
25.         Income = input.Income,
26.         Region = input.Region,
27.         PurchaseHistory = input.PurchaseHistory
28.     };
29.     var prediction = pool.Predict(data);
30.     return Results.Ok(new
31.     {
32.         Churned = prediction.PredictedLabel,
33.         Probability = prediction.Probability,
34.         Score = prediction.Score
35.     });
36. });
37. 
