40. static void TrainModel(string dataPath, string modelPath)
41. {
42.     var mlContext = new MLContext(seed: 42);
43. 
44.     var data = mlContext.Data.LoadFromTextFile<CustomerData>(
45.         dataPath, hasHeader: true, separatorChar: ',');
46. 
47.     var pipeline = mlContext.Transforms.CustomMapping<CustomerData, ChurnLabel>(
48.             (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
49.             contractName: "ChurnMapping")
50.         .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
51.         .Append(mlContext.Transforms.Concatenate("Features",
52.             nameof(CustomerData.Age),
53.             nameof(CustomerData.Income),
54.             nameof(CustomerData.PurchaseHistory),
55.             "RegionEncoded"))
56.         .Append(mlContext.Transforms.NormalizeMinMax("Features"))
57.         .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
58.             labelColumnName: "Label", featureColumnName: "Features"));
59. 
60.     long rowCount = data.GetColumn<float>(nameof(CustomerData.Age)).Count();
61. 
62.     if (rowCount >= 10)
63.     {
64.         var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
65.         var model = pipeline.Fit(split.TrainSet);
66. 
67.         var predictions = model.Transform(split.TestSet);
68.         var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
69.         Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
70. 
71.         mlContext.Model.Save(model, data.Schema, modelPath);
72.     }
73.     else
74.     {
75.         Console.WriteLine($"Warning: Only {rowCount} rows — training on full dataset without evaluation. Add more data for reliable metrics.");
76.         var model = pipeline.Fit(data);
77.         mlContext.Model.Save(model, data.Schema, modelPath);
78.     }
79. 
80.     Console.WriteLine($"Model saved to {modelPath}");
81. }
