 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 // Train and save the model at startup
 var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
 TrainModel(dataPath, modelPath);

 // Register pooled prediction engine (thread-safe for web use)
 builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapGet("/", () => "Churn Predictor API — POST to /predict");

 app.MapPost("/predict", (CustomerInput input, PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
 {
     var data = new CustomerData
     {
         Age = input.Age,
         Income = input.Income,
         Region = input.Region,
         PurchaseHistory = input.PurchaseHistory
     };
     var prediction = pool.Predict(data);
     return Results.Ok(new
     {
         Churned = prediction.PredictedLabel,
         Probability = prediction.Probability,
         Score = prediction.Score
     });
 });

 app.Run();

 static void TrainModel(string dataPath, string modelPath)
 {
     var mlContext = new MLContext(seed: 42);

     var data = mlContext.Data.LoadFromTextFile<CustomerData>(
         dataPath, hasHeader: true, separatorChar: ',');

     var lookupKeys = new[] { "Yes", "No" };
     var lookupValues = new[] { true, false };

     var pipeline = mlContext.Transforms.Conversion.MapValue(
             "Label", new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false },
             inputColumnName: nameof(CustomerData.Churned))
         .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
         .Append(mlContext.Transforms.Concatenate("Features",
             nameof(CustomerData.Age),
             nameof(CustomerData.Income),
             nameof(CustomerData.PurchaseHistory),
             "RegionEncoded"))
         .Append(mlContext.Transforms.NormalizeMinMax("Features"))
         .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
             labelColumnName: "Label", featureColumnName: "Features"));

     long rowCount = data.GetColumn<float>(nameof(CustomerData.Age)).Count();

     if (rowCount >= 10)
     {
         var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
         var model = pipeline.Fit(split.TrainSet);

         var predictions = model.Transform(split.TestSet);
         var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
         Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");

         mlContext.Model.Save(model, data.Schema, modelPath);
     }
     else
     {
         Console.WriteLine($"Warning: Only {rowCount} rows — training on full dataset without evaluation. Add more data for reliable metrics.");
         var model = pipeline.Fit(data);
         mlContext.Model.Save(model, data.Schema, modelPath);
     }

     Console.WriteLine($"Model saved to {modelPath}");
 }

